"""Supply named WETH positions once, with optional timed withdrawal."""

from almanak_v3.caip import AssetType
from almanak_v3.lending import Decision, DecisionInput, LendingConfig, Memory, OutcomeInput


def validate_config(config: LendingConfig) -> None:
    for allocation in config.allocations:
        chain = allocation.reserve.chain.chain_id
        weth = AssetType(f"{chain}/erc20:0xc02aaa39b223fe8d0a0e5c4f27ead9083c756cc2")
        if allocation.reserve.asset != weth:
            raise ValueError(f"{allocation.name}: this strategy requires the WETH reserve")


def decide(context: DecisionInput) -> Decision:
    observations = {item.allocation: item for item in context.observations}
    owned = {item.target.allocation: item.shares for item in context.owned}
    supplied_at = context.memory.values.get("supplied_at", {})
    for allocation in context.config.allocations:
        observed = observations[allocation.name]
        intent = decide_allocation(context, allocation, observed, owned, supplied_at)
        if intent is not None:
            return Decision(memory=context.memory, intent=intent)
    return Decision(memory=context.memory)


def decide_allocation(context, allocation, observed, owned, supplied_at):
    name = allocation.name
    started = supplied_at.get(name)
    due = (
        started is not None
        and allocation.hold_seconds is not None
        and observed.position.reserve.block.timestamp >= started + allocation.hold_seconds
    )
    if context.teardown or due:
        if owned[name] or observed.allowance:
            return context.config.withdraw(name)
        return None
    if started is None:
        return context.config.supply(name, allocation.amount)
    return None


def on_outcome(context: OutcomeInput) -> Memory:
    result = context.result
    if not (result.success and result.complete and result.intent.kind == "supply"):
        return context.memory
    supplied_at = dict(context.memory.values.get("supplied_at", {}))
    supplied_at[result.intent.target.allocation] = result.block.timestamp
    return Memory(
        version=context.memory.version,
        values={**context.memory.values, "supplied_at": supplied_at},
    )
